select c.name as city,count(distinct b.id)::integer as searchable_providers
from public.fd_directory_cities c join public.fd_directory_coverage v on v.city_id=c.id
join public.fd_directory_businesses b on b.id=v.business_id
where b.status='approved' and b.merged_into_id is null and b.data_origin<>'unverified' and b.service_flags->'grooming'='true'::jsonb
group by c.id,c.name order by c.name;
